  "/* === TICKETLELO UI FIXES === */\n\n    /* FAQ section: ensure visibility */\n    #faq {\n      display: block !important;\n      visibility: visible !important;\n      opacity: 1 !important;\n    }\n    .faq_item {\n      display: block !important;\n      visibility: visible !important;\n    }\n    .faq_header {\n      cursor: pointer;\n    }\n\n    /* Ensure sections that may be hidden are shown */\n    section.section {\n      display: block !important;\n    }\n\n    /* Refined Bar Chart / Column Diagram */\n    .column-diagram {\n      display: flex;\n      flex-direction: row;\n      width: 100%;\n      gap: 12px;\n      margin-top: 24px;\n      align-items: flex-end;\n    }\n    .column-box {\n      display: flex;\n      flex-direction: column;\n      justify-content: flex-end;\n    }\n    /* Proportional flexible widths */\n    .column-box:nth-child(1) { flex: 6.5; }\n    .column-box:nth-child(2) { flex: 2.5; }\n    .column-box:nth-child(3) { flex: 1.0; min-width: 60px; } /* min-width to fit 10% text */\n\n    .column-box p {\n      margin-top: 0 !important;\n      margin-bottom: 12px !important;\n      text-align: left;\n      padding-left: 8px;\n      font-weight: 500;\n      white-space: nowrap;\n      position: static !important;\n      transform: none !important;\n    }\n    \n    .column-box .column {\n      position: relative;\n      height: 70px;\n      border-radius: 40px !important;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      overflow: hidden;\n      width: 100%;\n    }\n    \n    .column-box .text-size-34 {\n      position: absolute !important;\n      z-index: 5;\n      color: white;\n      font-weight: 600;\n      margin: 0;\n      left: 50%;\n      top: 50%;\n      transform: translate(-50%, -50%);\n    }\n\n    .progress {\n      position: absolute;\n      top: 0;\n      left: 0;\n      height: 100%;\n      width: 100%;\n      border-radius: 40px !important;\n      z-index: 1;\n    }\n    \n    @media screen and (max-width: 767px) {\n      .column-box .text-size-34 {\n        font-size: 20px !important;\n      }\n      .column-box p {\n        font-size: 11px !important;\n        white-space: normal;\n        margin-bottom: 6px !important;\n      }\n    }\n\n    /* Responsive: mobile cards and layout */\n    @media screen and (max-width: 767px) {\n      .new-pricing-wrapper {\n        flex-direction: column;\n      }\n      .content.is--pricing-light {\n        width: 100%;\n        min-width: 100%;\n      }\n      /* Fix pricing tab pills cutting off on mobile */\n      .pricing_tabs-menu.cent {\n        display: grid !important;\n        grid-template-columns: 1fr 1fr;\n        gap: 8px;\n        padding: 8px !important;\n        border-radius: 16px !important; /* Fix the broken capsule shape when wrapping */\n        height: auto !important;\n      }\n      .pricing_tabs-menu.cent .tab-link.o {\n        flex: 1 1 auto;\n        white-space: normal;\n        text-align: center;\n        padding: 10px 8px;\n        margin: 0 !important;\n        border-radius: 12px !important;\n        font-size: 14px !important;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n      }\n      /* Ensure navbar timer stacks correctly and is visible on small screens */\n      .timeline-wrapper {\n        flex-direction: column !important;\n        align-items: center !important;\n        text-align: center !important;\n        padding: 10px 0;\n        gap: 8px;\n      }\n      .sale-style .timer {\n        margin-right: 0 !important;\n        justify-content: center !important;\n        width: 100%;\n      }\n      .timeline-wrapper p {\n        margin-left: 0 !important;\n        font-size: 14px !important;\n      }\n    }\n\n    /* Cards: make them fill their container and be responsive */\n    .content.community-small {\n      min-height: 140px;\n      box-sizing: border-box;\n      width: 100%;\n    }\n\n    .new-pricing-wrapper {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 20px;\n    }\n    .content.is--pricing-light {\n      flex: 1 1 0%;\n      min-width: 280px;\n      box-sizing: border-box;\n      height: auto !important;\n      min-height: max-content !important;\n      padding-bottom: 32px !important;\n    }\n    \n    /* Ensure tab content wrappers stretch to fit the new lists */\n    .tabs-content-2, .w-tab-content, .w-tab-pane {\n      height: auto !important;\n      overflow: visible !important;\n    }\n\n    /* Responsive: mobile cards */\n    @media screen and (max-width: 767px) {\n      .new-pricing-wrapper {\n        flex-direction: column;\n      }\n      .content.is--pricing-light {\n        flex: 1 1 100%;\n        min-width: unset;\n        width: 100%;\n      }\n      .content.community-small {\n        min-height: 120px;\n      }\n      ._4-col-grid {\n        display: grid !important;\n        grid-template-columns: 1fr 1fr !important;\n        gap: 16px !important;\n      }\n    }\n    @media screen and (max-width: 479px) {\n      ._4-col-grid {\n        grid-template-columns: 1fr !important;\n      }\n    }\n\n    /* Timer: ensure always visible when .sale-style is shown */\n    .sale-style .timer {\n      display: flex !important;\n      align-items: center;\n      gap: 4px;\n      margin-right: 16px;\n    }\n    .timeline-wrapper p {\n      margin-left: 12px;\n      font-size: 1.1em;\n    }\n    .timer__days, .timer__hours, .timer__minutes, .timer__seconds {\n      display: inline-block;\n      min-width: 2ch;\n      font-variant-numeric: tabular-nums;\n    }\n\n    /* Preloader counter */\n    .count-wrapper {\n      display: flex;\n      align-items: baseline;\n      gap: 2px;\n    }\n    #preloader-count {\n      font-variant-numeric: tabular-nums;\n      min-width: 3ch;\n      display: inline-block;\n    }",
  ".tag-canvas>canvas {\n      position: relative;\n      top: -1px;\n      left: -1px;\n      right: -1px;\n    }"
