   "code": "new Swiper(\".swiper\", {\n        slidesPerView: 1,\n        grid: {\n          rows: 4,\n        },\n        spaceBetween: 0,\n        navigation: {\n          nextEl: \".swiper-right\",\n          prevEl: \".swiper-left\",\n        },\n      });"
